{"sql": "WITH wicket_balls AS (
    SELECT DISTINCT match_id, innings_no, ball_id FROM wicket_taken
),
wicket_seq AS (
    SELECT match_id, innings_no, ball_id,
           ROW_NUMBER() OVER (PARTITION BY match_id, innings_no ORDER BY ball_id) as wicket_seq
    FROM wicket_balls
)
SELECT * FROM wicket_seq WHERE match_id = 335987 ORDER BY innings_no, wicket_seq"}
